func findDuplicate(nums []int) int {
    slow, fast := nums[0], nums[nums[0]]
    // 找相遇点
    for slow != fast {
        slow = nums[slow]
        fast = nums[nums[fast]]
    }
    // 找入环点
    slow = 0
    for slow != fast {
        slow = nums[slow]
        fast = nums[fast]
    }
    return slow
}
